use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < 'a , Ty > TyAndLayout < 'a , Ty > { pub fn for_variant < C > (self , cx : & C , variant_index : VariantIdx) -> Self where Ty : TyAbiInterface < 'a , C > , { Ty :: ty_and_layout_for_variant (self , cx , variant_index) } pub fn field < C > (self , cx : & C , i : usize) -> Self where Ty : TyAbiInterface < 'a , C > , { Ty :: ty_and_layout_field (self , cx , i) } pub fn pointee_info_at < C > (self , cx : & C , offset : Size) -> Option < PointeeInfo > where Ty : TyAbiInterface < 'a , C > , { Ty :: ty_and_layout_pointee_info_at (self , cx , offset) } pub fn is_single_fp_element < C > (self , cx : & C) -> bool where Ty : TyAbiInterface < 'a , C > , C : HasDataLayout , { match self . backend_repr { BackendRepr :: Scalar (scalar) => { matches ! (scalar . primitive () , Primitive :: Float (Float :: F32 | Float :: F64)) } BackendRepr :: Memory { .. } => { if self . fields . count () == 1 && self . fields . offset (0) . bytes () == 0 { self . field (cx , 0) . is_single_fp_element (cx) } else { false } } _ => false , } } pub fn is_single_vector_element < C > (self , cx : & C , expected_size : Size) -> bool where Ty : TyAbiInterface < 'a , C > , C : HasDataLayout , { match self . backend_repr { BackendRepr :: SimdVector { .. } => self . size == expected_size , BackendRepr :: Memory { .. } => { if self . fields . count () == 1 && self . fields . offset (0) . bytes () == 0 { self . field (cx , 0) . is_single_vector_element (cx , expected_size) } else { false } } _ => false , } } pub fn is_adt < C > (self) -> bool where Ty : TyAbiInterface < 'a , C > , { Ty :: is_adt (self) } pub fn is_never < C > (self) -> bool where Ty : TyAbiInterface < 'a , C > , { Ty :: is_never (self) } pub fn is_tuple < C > (self) -> bool where Ty : TyAbiInterface < 'a , C > , { Ty :: is_tuple (self) } pub fn is_unit < C > (self) -> bool where Ty : TyAbiInterface < 'a , C > , { Ty :: is_unit (self) } pub fn is_transparent < C > (self) -> bool where Ty : TyAbiInterface < 'a , C > , { Ty :: is_transparent (self) } # [doc = " Finds the one field that is not a 1-ZST."] # [doc = " Returns `None` if there are multiple non-1-ZST fields or only 1-ZST-fields."] pub fn non_1zst_field < C > (& self , cx : & C) -> Option < (FieldIdx , Self) > where Ty : TyAbiInterface < 'a , C > + Copy , { let mut found = None ; for field_idx in 0 .. self . fields . count () { let field = self . field (cx , field_idx) ; if field . is_1zst () { continue ; } if found . is_some () { return None ; } found = Some ((FieldIdx :: from_usize (field_idx) , field)) ; } found } }
}